94	    public OwnerRestControllerV1(ClinicService clinicService,
95	                                 OwnerMapper ownerMapper,
96	                                 PetMapper petMapper,
97	                                 VisitMapper visitMapper,
98	                                 TelephoneNormalizer telephoneNormalizer,
99	                                 AddressNormalizer addressNormalizer,
100	                                 EmailNormalizer emailNormalizer,
101	                                 DisposableEmailDomains disposableEmailDomains) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	        this.telephoneNormalizer = telephoneNormalizer;
107	        this.addressNormalizer = addressNormalizer;
108	        this.emailNormalizer = emailNormalizer;
109	        this.disposableEmailDomains = disposableEmailDomains;
110	    }
