112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
115	        Collection<Owner> owners;
116	        if (lastName != null) {
117	            owners = this.clinicService.findOwnerByLastName(lastName);
118	        } else {
119	            owners = this.clinicService.findAllOwners();
120	        }
121	        if (owners.isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
130	        return withOwner(ownerId, owner ->
131	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
137	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
138	        rejectBlankOwnerFields(ownerFieldsDto);
139	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
140	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
141	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
142	        rejectCityAtCapacity(ownerFieldsDto.getCity());
143	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
144	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
145	        rejectDailyRegistrationLimit(registrationDate);
146	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
147	        ownerFieldsDto.setTelephone(normalizedTelephone);
148	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
149	        ownerFieldsDto.setEmail(normalizedEmail);
150	        HttpHeaders headers = new HttpHeaders();
151	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
152	        owner.setRegistrationDate(registrationDate);
153	        owner.setCustomerCode(customerCode(owner));
154	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
155	        owner.setHouseholdId(householdId(owner));
156	        rejectDuplicateIdentity(owner);
157	        rejectHouseholdDuplicate(owner, sharesHousehold);
158	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
159	        this.clinicService.saveOwner(owner);
160	        owner.setHouseholdSize(householdSize(owner));
161	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
162	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
163	            ownerMapper.membershipLevel(owner));
164	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
165	        headers.setLocation(UriComponentsBuilder.newInstance()
166	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
167	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
173	        return withOwner(ownerId, currentOwner -> {
174	            currentOwner.setAddress(ownerFieldsDto.getAddress());
175	            currentOwner.setCity(ownerFieldsDto.getCity());
176	            currentOwner.setFirstName(ownerFieldsDto.getFirstName());
177	            currentOwner.setLastName(ownerFieldsDto.getLastName());
178	            currentOwner.setTelephone(ownerFieldsDto.getTelephone());
179	            currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
180	            this.clinicService.saveOwner(currentOwner);
181	            return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
182	        });
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Transactional
187	    @Override
188	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
189	        return withOwner(ownerId, owner -> {
190	            this.clinicService.deleteOwner(owner);
191	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
192	        });
193	    }
