195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
198	        return withOwner(ownerId, owner -> {
199	            HttpHeaders headers = new HttpHeaders();
200	            Pet pet = petMapper.toPet(petFieldsDto);
201	            owner.setId(ownerId);
202	            pet.setOwner(owner);
203	            pet.getType().setName(null);
204	            this.clinicService.savePet(pet);
205	            PetDto petDto = petMapper.toPetDto(pet);
206	            headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
207	                .buildAndExpand(pet.getId()).toUri());
208	            return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
209	        });
210	    }
