244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner != null) {
250	            Pet pet = owner.getPet(petId);
251	            if (pet != null) {
252	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
253	            }
254	        }
255	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	    }
257	
258	    /**
259	     * Loads the owner with the given id and, when it exists, produces the response through
260	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
261	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
262	     * the not-found response are written in exactly one place rather than copied into each method.
263	     *
264	     * @param ownerId the id of the owner to load
265	     * @param action builds the response for an existing owner
266	     * @param <T> the response body type
267	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
268	     */
269	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
270	        Owner owner = this.clinicService.findOwnerById(ownerId);
271	        if (owner == null) {
272	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
273	        }
274	        return action.apply(owner);
275	    }
276	
277	    /**
278	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
279	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag
280	     * and the {@code identityKey}). Both the create endpoint and the single-owner read endpoint
281	     * return their owner through this method, so an owner is decorated identically on either path
282	     * and each derived field is computed in exactly one place.
283	     *
284	     * @param owner the persisted owner to represent
285	     * @return the owner DTO with its derived read-only fields populated
286	     */
287	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
288	        owner.setHouseholdSize(householdSize(owner));
289	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
290	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
291	        ownerDto.setIdentityKey(identityKey(owner));
292	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
293	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
294	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
295	        return ownerDto;
296	    }
297	
298	    /**
299	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
300	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
301	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
302	     * blank (e.g. {@code "   "}). The offending field names are reported through an
303	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
304	     * as a 400 response carrying an {@code errors} array of field names.
305	     *
306	     * @param ownerFieldsDto the submitted owner fields
307	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
308	     */
309	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
310	        List<String> blankFields = new ArrayList<>();
311	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
312	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
313	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
314	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
315	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
316	        if (!blankFields.isEmpty()) {
317	            throw new InvalidOwnerFieldsException(blankFields);
318	        }
319	    }
320	
321	    private void addIfBlank(List<String> blankFields, String field, String value) {
322	        if (value != null && value.isBlank()) {
323	            blankFields.add(field);
324	        }
325	    }
326	
327	    /**
328	     * Rejects an owner whose {@code email} domain is on the disposable-domain blocklist
329	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is validated
330	     * only when present, so an owner created without one is accepted unchanged; syntactic validity is
331	     * already enforced by Bean Validation's {@code @Email} constraint on {@link OwnerFieldsDto}, so
332	     * this only rejects an otherwise well-formed address that uses a throwaway provider (see
333	     * {@link DisposableEmailDomains#isDisposable(String)} for the case-insensitive domain match). A
334	     * blocklisted address is reported through a {@link DisposableEmailDomainException}, which the
335	     * {@code ExceptionControllerAdvice} renders as a 400 response naming the {@code email} field.
336	     *
337	     * @param email the supplied email, or {@code null} when omitted
338	     * @throws DisposableEmailDomainException if the email's domain is blocklisted
339	     */
340	    private void rejectDisposableEmailDomain(String email) {
341	        if (disposableEmailDomains.isDisposable(email)) {
342	            throw new DisposableEmailDomainException(email);
343	        }
344	    }
345	
346	    /**
347	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
348	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
349	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
350	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
351	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
352	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
353	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
354	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
355	     *
356	     * @param city the city of the owner being created
357	     * @param postcode the supplied postcode, or {@code null} when omitted
358	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
359	     */
360	    private void rejectInvalidPostcode(String city, String postcode) {
361	        if (postcode == null || postcode.isBlank()) {
362	            return;
363	        }
364	        Region.forCity(city).ifPresent(region -> {
365	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
366	                throw new InvalidOwnerPostcodeException(postcode, city);
367	            }
368	        });
369	    }
370	
371	    /**
372	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
373	     * the {@code customerCode}.
374	     */
375	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
376	
377	    /**
378	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
379	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
380	     * its {@code postcode} (falling back to its {@code city}) through the shared
381	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
382	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
383	     * (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a deterministic
384	     * function of the owner's region and telephone-plus-name identity.
385	     *
386	     * @param owner the owner being created, with its telephone already normalized
387	     * @return the formatted customer code
388	     */
389	    private String customerCode(Owner owner) {
390	        String region = Region.code(owner.getPostcode(), owner.getCity());
391	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
392	        return region + "-" + hash8;
393	    }
394	
395	    /**
396	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
397	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
398	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
399	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
400	     * new owner and surfaced as the read-only {@code namesakeCount} field.
401	     *
402	     * @param firstName the first name of the owner being created
403	     * @param lastName the last name of the owner being created
404	     * @return the number of existing owners with the same first and last name (case-insensitive)
405	     */
406	    private int namesakeCount(String firstName, String lastName) {
407	        return (int) countOwners(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
408	            && equalsIgnoreCase(owner.getLastName(), lastName));
409	    }
410	
411	    private boolean equalsIgnoreCase(String a, String b) {
412	        return a == null ? b == null : a.equalsIgnoreCase(b);
413	    }
414	
415	    /**
416	     * The maximum number of owners a single city may contain. Once a city already holds this many
417	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
418	     */
419	    private static final long MAX_OWNERS_PER_CITY = 50L;
420	
421	    /**
422	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
423	     * owners. Existing owners are matched to the requested city case-insensitively (using
424	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
425	     * the per-city counting used for the customer code. A city at capacity is reported through an
426	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
427	     * 409 Conflict response.
428	     *
429	     * @param city the city of the owner being created
430	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
431	     */
432	    private void rejectCityAtCapacity(String city) {
433	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
434	            throw new OwnerCityAtCapacityException(city);
435	        }
436	    }
437	
438	    /**
439	     * Counts the existing owners whose {@code city} matches the given city, compared
440	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Used by the per-city
441	     * capacity check ({@link #rejectCityAtCapacity(String)}) to count a city's owners.
442	     *
443	     * @param city the city to count owners for
444	     * @return the number of existing owners in that city
445	     */
446	    private long ownersInCity(String city) {
447	        return countOwners(owner -> equalsIgnoreCase(owner.getCity(), city));
448	    }
449	
450	    /**
451	     * The maximum number of owners that may be registered on a single day. Once this many owners
452	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
453	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
454	     */
455	    private static final long MAX_OWNERS_PER_DAY = 100L;
456	
457	    /**
458	     * Resolves the effective registration date for a create request: the value supplied in the
459	     * request when present, otherwise the server's current date. The result is the raw effective
460	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
461	     *
462	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
463	     * @return the supplied date, or today when none was supplied
464	     */
465	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
466	        return suppliedDate != null ? suppliedDate : LocalDate.now();
467	    }
468	
469	    /**
470	     * Rejects a create request whose supplied {@code registrationDate} lies after the server's
