140	     * Maps the owner's {@code membershipPoints} to its numeric {@code membershipLevel}: level
141	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
142	     * {@code 4} for {@code 6} or more points.
143	     *
144	     * @param owner the owner being mapped
145	     * @return the derived membership level, between {@code 1} and {@code 4}
146	     */
147	    default Integer membershipLevel(Owner owner) {
148	        int points = membershipPoints(owner);
149	        if (points <= 1) {
150	            return 1;
151	        }
152	        if (points <= 3) {
153	            return 2;
154	        }
155	        if (points <= 5) {
156	            return 3;
157	        }
158	        return 4;
159	    }
160	
161	    /**
162	     * Computes the owner's tenure in whole days: the number of complete days between the owner's
163	     * {@code registrationDate} and the current date. Returns {@code 0} when no registration date is
164	     * present, so an owner without a registration date has no tenure.
165	     *
166	     * @param owner the owner being mapped
167	     * @return the owner's tenure in whole days, or {@code 0} when no registration date is present
168	     */
169	    default long tenureDays(Owner owner) {
170	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
171	        if (registrationDate == null) {
172	            return 0;
173	        }
174	        return java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
175	    }
176	
177	    /**
178	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
179	     * where {@code YY} is the last two digits of the {@code registrationDate} year (e.g.
180	     * {@code 'NSW-1A2B3C4D-M26'}). Returns {@code null} when either the customer code or the
181	     * registration date is absent.
182	     *
183	     * @param owner the owner being mapped
184	     * @return the formatted membership number, or {@code null} when it cannot be derived
185	     */
186	    default String membershipNumber(Owner owner) {
187	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
188	            return null;
189	        }
190	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
191	    }
192	
193	    /**
194	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
195	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<REGION>-'}
196	     * prefix, the separator and the hex letters {@code A-F}, are ignored). Returns {@code null} when
197	     * the customer code is absent.
198	     *
199	     * @param owner the owner being mapped
200	     * @return the Luhn check digit, or {@code null} when no customer code is present
201	     */
202	    default Integer checkDigit(Owner owner) {
203	        String code = owner.getCustomerCode();
204	        if (code == null) {
205	            return null;
206	        }
207	        int sum = 0;
208	        boolean dbl = true;
209	        for (int i = code.length() - 1; i >= 0; i--) {
210	            char c = code.charAt(i);
211	            if (c < '0' || c > '9') {
212	                continue;
213	            }
214	            int d = c - '0';
215	            if (dbl) {
216	                d *= 2;
217	                if (d > 9) {
218	                    d -= 9;
219	                }
220	            }
221	            sum += d;
222	            dbl = !dbl;
223	        }
224	        return (10 - (sum % 10)) % 10;
225	    }
226	
227	    /**
228	     * Formats the owner's stored E.164 {@code telephone} for human display: the country calling
229	     * code, a space, then the national-significant digits grouped in threes separated by spaces
230	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw {@code telephone}
231	     * field keeps the unformatted E.164 value. The split between the country code and the national
232	     * digits mirrors the recognised calling codes of the {@code TelephoneNormalizer}: Australian
233	     * {@code +61} (9 national digits) and North American {@code +1} (10); an unrecognised or
234	     * malformed value falls back to a single leading digit. Returns the value unchanged when it is
235	     * {@code null}, blank, or not in E.164 form.
236	     *
237	     * @param owner the owner being mapped
238	     * @return the human-formatted telephone, or the raw value when it cannot be formatted
239	     */
240	    default String telephoneDisplay(Owner owner) {
241	        String telephone = owner.getTelephone();
242	        if (telephone == null || telephone.isBlank() || !telephone.startsWith("+")) {
243	            return telephone;
244	        }
245	        String digits = telephone.substring(1);
246	        int codeLength = (digits.startsWith("61") && digits.length() == 2 + 9) ? 2 : 1;
247	        String countryCode = digits.substring(0, codeLength);
248	        String national = digits.substring(codeLength);
249	        StringBuilder grouped = new StringBuilder();
250	        for (int i = 0; i < national.length(); i++) {
251	            if (i > 0 && i % 3 == 0) {
252	                grouped.append(' ');
253	            }
254	            grouped.append(national.charAt(i));
255	        }
256	        return "+" + countryCode + " " + grouped;
257	    }
258	
259	    Owner toOwner(OwnerDto ownerDto);
260	
261	    @Mapping(target = "id", ignore = true)
262	    @Mapping(target = "pets", ignore = true)
263	    Owner toOwner(OwnerFieldsDto ownerDto);
264	
265	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
266	
267	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
268	
269	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
270	        OwnerPageDto ownerPageDto = new OwnerPageDto();
271	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
272	        ownerPageDto.setPage(ownerPage.getNumber());
273	        ownerPageDto.setSize(ownerPage.getSize());
274	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
275	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
276	        return ownerPageDto;
277	    }
278	}
