2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	import org.springframework.stereotype.Component;
7	
8	/**
9	 * Normalizes owner postal addresses into the single canonical form that is stored, returned and
10	 * compared when an owner is created. Keeping this logic in one place lets the create endpoint treat
11	 * an address as an opaque, already-canonical value: it {@link #normalize(String) normalizes} an
12	 * incoming address once, then relies on that same form for the required-field check, household
13	 * duplicate detection and the shared household id.
14	 *
15	 * <p>Normalization trims and collapses whitespace, upper-cases the result (using
16	 * {@link Locale#ROOT} so it is locale-independent) and expands a small set of common street-type
17	 * abbreviations applied to whole words only ({@code ST -> STREET}, {@code RD -> ROAD},
18	 * {@code AVE -> AVENUE}). For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
19	 */
20	@Component
21	public class AddressNormalizer {
22	
23	    /** Whole-word abbreviation -> expansion, matched against upper-cased tokens. */
24	    private static final Map<String, String> ABBREVIATIONS = Map.of(
25	        "ST", "STREET",
26	        "RD", "ROAD",
27	        "AVE", "AVENUE");
28	
29	    /**
30	     * Normalizes an address submitted to the create endpoint: leading and trailing whitespace is
31	     * trimmed, every run of internal whitespace is collapsed to a single space, the result is
32	     * upper-cased and common street-type abbreviations are expanded on a whole-word basis. A
33	     * {@code null} address is left as-is; a value that is blank (whitespace-only) collapses to an
34	     * empty string.
35	     *
36	     * @param address the raw address value from the request, or {@code null} when omitted
37	     * @return the normalized address to store and return, or {@code null} when none was supplied
38	     */
39	    public String normalize(String address) {
40	        if (address == null) {
41	            return null;
42	        }
43	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
44	        if (collapsed.isEmpty()) {
45	            return collapsed;
46	        }
47	        String[] tokens = collapsed.split(" ");
48	        StringBuilder sb = new StringBuilder(collapsed.length());
49	        for (int i = 0; i < tokens.length; i++) {
50	            if (i > 0) {
51	                sb.append(' ');
52	            }
53	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
54	        }
55	        return sb.toString();
56	    }
57	}
