16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Map;
19	import java.util.Optional;
20	
21	/**
22	 * The Australian region an owner's city belongs to. Each constant's name is the canonical region
23	 * code as stored and returned (e.g. {@code "NSW"}). Regions are resolved from a single fixed
24	 * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD});
25	 * a city that is not in the table has no known region.
26	 *
27	 * <p>This is the one place the city-to-region mapping lives, so every rule that keys off an owner's
28	 * region - such as the derived {@code locality} - resolves it identically.
29	 */
30	public enum Region {
31	
32	    NSW(2000, 2099),
33	    VIC(3000, 3099),
34	    QLD(4000, 4099);
35	
36	    private final int minPostcode;
37	
38	    private final int maxPostcode;
39	
40	    Region(int minPostcode, int maxPostcode) {
41	        this.minPostcode = minPostcode;
42	        this.maxPostcode = maxPostcode;
43	    }
44	
45	    /** Fixed city -> region table; a city absent from this map has no known region. */
46	    private static final Map<String, Region> BY_CITY = Map.of(
47	        "Sydney", NSW,
48	        "Melbourne", VIC,
49	        "Brisbane", QLD);
50	
51	    /** Canonical region code returned when neither the postcode nor the city resolves to a region. */
52	    public static final String UNKNOWN_CODE = "UNKNOWN";
53	
54	    /**
55	     * Reports whether the given 4-digit postcode falls within this region's inclusive postcode range
56	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). This is the one place the region-to-postcode
57	     * range lives, so every rule that validates a postcode against an owner's region resolves it
58	     * identically.
59	     *
60	     * @param postcode the numeric value of the owner's 4-digit postcode
61	     * @return {@code true} when the postcode is within this region's range
62	     */
63	    public boolean acceptsPostcode(int postcode) {
64	        return postcode >= this.minPostcode && postcode <= this.maxPostcode;
65	    }
66	
67	    /**
68	     * Resolves the region for the given city from the fixed city-to-region table.
69	     *
70	     * @param city the owner's city, or {@code null}
71	     * @return the matching region, or empty when the city is {@code null} or has no known region
72	     */
73	    public static Optional<Region> forCity(String city) {
74	        return city == null ? Optional.empty() : Optional.ofNullable(BY_CITY.get(city));
75	    }
76	
77	    /**
78	     * Resolves the region whose postcode range contains the given 4-digit postcode
79	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
80	     *
81	     * @param postcode the owner's 4-digit postcode, or {@code null}
82	     * @return the matching region, or empty when the postcode is {@code null}, not numeric, or in no
83	     *         known range
84	     */
85	    public static Optional<Region> forPostcode(String postcode) {
86	        if (postcode == null) {
87	            return Optional.empty();
88	        }
89	        int value;
90	        try {
91	            value = Integer.parseInt(postcode.trim());
92	        } catch (NumberFormatException ex) {
93	            return Optional.empty();
94	        }
95	        for (Region region : values()) {
96	            if (region.acceptsPostcode(value)) {
97	                return Optional.of(region);
98	            }
99	        }
100	        return Optional.empty();
101	    }
102	
103	    /**
104	     * Resolves the canonical region code for an owner located at the given {@code postcode} and
105	     * {@code city}, preferring the postcode: it first looks up the region by
106	     * {@link #forPostcode(String) postcode range} (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and
107	     * only falls back to the {@link #forCity(String) city-to-region} table ({@code Sydney -> NSW},
108	     * {@code Melbourne -> VIC}, {@code Brisbane -> QLD}) when the postcode is absent or in no known
109	     * range. Returns the region's code, or {@link #UNKNOWN_CODE} when neither resolves.
110	     *
111	     * <p>This is the one place an owner's postcode and city are turned into a region code, so every
112	     * rule that labels an owner by region resolves it identically.
113	     *
114	     * @param postcode the owner's 4-digit postcode, or {@code null}
115	     * @param city the owner's city, or {@code null}
116	     * @return the canonical region code, or {@link #UNKNOWN_CODE} when neither postcode nor city resolves
117	     */
118	    public static String code(String postcode, String city) {
119	        return forPostcode(postcode)
120	            .or(() -> forCity(city))
121	            .map(Region::name)
122	            .orElse(UNKNOWN_CODE);
123	    }
124	}
